fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    if strings.is_empty() {
        return None;
    }

    // Track index of the longest sequence found so far and its length
    let mut max_index = 0;
    let mut max_len = 0;

    for (i, seq) in strings.iter().enumerate() {
        let len = seq.len();
        if len > max_len {
            max_len = len;
            max_index = i;
        }
    }

    // Return a clone of the sequence at max_index wrapped in Some
    Some(strings[max_index].clone())
}